<script setup lang="ts">
import type {PublicQuestion} from '@/api/quiz'
const props=defineProps<{questions:PublicQuestion[];currentId:string;choices:Record<string,string|null>;disabled:boolean;originalNumbers?:Record<string,number>}>();const emit=defineEmits<{choose:[id:string,choice:string|null];navigate:[id:string]}>()
function number(q:PublicQuestion,i:number){return props.originalNumbers?.[q.id]??i+1}
function stem(q:PublicQuestion){return props.originalNumbers?.[q.id]?q.stem.replace(/^\d+[.、]\s*/,''):q.stem}
</script>
<template><section class="practice-panel practice-answer-panel"><h2>本组题目</h2><div class="practice-question-numbers" aria-label="作答题号"><button v-for="(q,i) in questions" :key="q.id" :aria-pressed="q.id===currentId" @click="emit('navigate',q.id)">{{number(q,i)}}<small>{{choices[q.id]?'已选'+choices[q.id]:'未答'}}</small></button></div><template v-for="(q,i) in questions" :key="q.id"><fieldset v-if="q.id===currentId" :disabled="disabled"><legend><h3>{{number(q,i)}}. {{stem(q)}}</h3></legend><label v-for="(option,n) in q.options" :key="n" class="practice-option"><input type="radio" :name="q.id" :checked="choices[q.id]==='ABCD'[n]" @change="emit('choose',q.id,'ABCD'[n]!)"><span>{{'ABCD'[n]}}. {{option}}</span></label><button type="button" :disabled="!choices[q.id]" @click="emit('choose',q.id,null)">清空本题选项</button><div class="practice-question-steps"><button type="button" :disabled="i===0" @click="emit('navigate',questions[i-1]!.id)">上一题</button><button type="button" :disabled="i===questions.length-1" @click="emit('navigate',questions[i+1]!.id)">下一题</button></div></fieldset></template></section></template>
